 static ConnectionFactory Factory(){var f=new ConnectionFactory(Cs);Func<SqlConnection,CancellationToken,Task> a=async(c,ct)=>{await using var cmd=c.CreateCommand();cmd.CommandText="EXECUTE AS USER=N'G02_Runtime'";await cmd.ExecuteNonQueryAsync(ct);};typeof(ConnectionFactory).GetProperty("SessionInitializer",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(f,a);return f;}
 static async Task<string> Snapshot(){var all="";foreach(var (table,key) in new[]{("DANHMUC_SP","MaDM"),("NHACUNGCAP","MaNCC"),("PHUONGTHUCTT","MaPT"),("DOITACGIAOHANG","MaDT"),("DANHMUC_THUCHI","MaDMTC"),("CHUCVU","MaCV"),("CALAMVIEC","MaCa")})all+=await Sql($"SELECT (SELECT * FROM dbo.{table} ORDER BY {key} FOR JSON PATH,INCLUDE_NULL_VALUES)");return Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(all)));}
 delegate bool EnumWindow(IntPtr h,IntPtr a);[DllImport("user32.dll")]static extern bool EnumWindows(EnumWindow c,IntPtr a);[DllImport("user32.dll")]static extern int GetWindowThreadProcessId(IntPtr h,out int pid);[DllImport("user32.dll")]static extern IntPtr GetDlgItem(IntPtr h,int id);[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool PrintWindow(IntPtr h,IntPtr dc,uint flags);
