 [STAThread]static int Main(string[] args){Db=args[0];Output=args[1];Directory.CreateDirectory(Output);Need(System.Text.RegularExpressions.Regex.IsMatch(Db,@"^CoffeeManager_Test_G02_\d{8}_\d{6}_[a-f0-9]{8}$"),"Isolated DB required");Need(Convert.ToInt32(Sql("SELECT COUNT(*) FROM dbo.G02TestMarker").GetAwaiter().GetResult())==1,"Marker missing");Password=Convert.ToBase64String(RandomNumberGenerator.GetBytes(24));Sql("UPDATE dbo.TAIKHOAN SET MatKhauHash=@hash WHERE TenDangNhap IN('g02.admin','g02.cash','g02.store')",new SqlParameter("@hash",new PasswordService().Hash(Password))).GetAwaiter().GetResult();Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var r=new AuthRepository(Factory());var p=new PermissionService(r);var s=new CatalogService(new CatalogRepository(Factory()),p);var type=typeof(MainForm).Assembly.GetType("CafeManager.WinForms.ApplicationSessionContext")!;Context=(ApplicationContext)Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public,null,[new AuthService(r,new PasswordService()),p,r,null,(Func<SessionContext,UserControl>)(x=>new CatalogsControl(s,x))],null)!;type.GetMethod("Start")!.Invoke(Context,null);var t=new System.Windows.Forms.Timer{Interval=100};t.Tick+=async(_,_)=>{t.Stop();try{await Cases();}catch(Exception e){Results.Add(new{Id="HARNESS",Status="BLOCKED",Actual=e.Message});}finally{File.WriteAllText(Path.Combine(Output,"ui-extra.json"),JsonSerializer.Serialize(Results,new JsonSerializerOptions{WriteIndented=true}));Context.ExitThread();}};t.Start();Application.Run(Context);return Results.Any(x=>JsonSerializer.Serialize(x).Contains("\"FAIL\""))?1:0;}
 static async Task LoginAs(string role){F<TextBox>(Login,"usernameInput").Text="g02."+role.ToLowerInvariant();F<TextBox>(Login,"passwordInput").Text=Password;F<Button>(Login,"loginButton").PerformClick();await Wait(()=>Current is {Visible:true});await Task.Delay(250);await Wait(()=>!F<bool>(Current!,"navigating")&&F<Panel>(Current!,"content").Controls.Count==1);if(role=="ADMIN")await Wait(()=>V((CatalogsControl)F<Panel>(Current!,"content").Controls[0],"loading")==null);}
 static async Task Cases(){
  foreach(var role in new[]{"CASH","STORE","ADMIN"}){
   await Check("T07-K01.ready."+role,"Start page appears after Shown/recheck finishes",async()=>{await LoginAs(role);var child=F<Panel>(Current!,"content").Controls[0];Need(role=="ADMIN"?child is CatalogsControl:child.GetType().Name=="SessionHomeControl","Wrong start control");Capture(Current!,"ready-"+role);return "One native start control, role/name matched; screenshot after readiness";});
   if(role!="ADMIN")await Check("T07-K02.direct."+role,"Unauthorized navigation keeps current page",async()=>{var child=F<Panel>(Current!,"content").Controls[0];await (Task)typeof(MainForm).GetMethod("Navigate",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(Current,[CafeManager.WinForms.Navigation.NavigationTarget.Catalogs])!;Need(ReferenceEquals(child,F<Panel>(Current!,"content").Controls[0]),"Unauthorized replaced page");return "Denied, current start control retained";});
   if(role=="ADMIN"){
    var control=(CatalogsControl)F<Panel>(Current!,"content").Controls[0];
    foreach(var kind in Enum.GetValues<CatalogKind>())await Check("T07-K06.exact-cancel."+kind,"No catalog row/field/revision changes on dirty cancel",async()=>{F<TabControl>(control,"tabs").SelectedIndex=(int)kind;await Wait(()=>V(control,"loading")==null);var before=await Snapshot();Current!.BeginInvoke((Action)(()=>F<Button>(control,"addButton").PerformClick()));await Wait(()=>Application.OpenForms.OfType<CatalogEditorDialog>().Any());var d=Application.OpenForms.OfType<CatalogEditorDialog>().Single();F<TextBox>(d,"nameInput").Text="Dirty exact cancel";await Cancel(d,false);Need(!d.IsDisposed&&F<TextBox>(d,"nameInput").Text=="Dirty exact cancel","No did not retain draft");Need(before==await Snapshot(),"Stay wrote data");await Cancel(d,true);await Wait(()=>d.IsDisposed);Need(before==await Snapshot(),"Cancel changed catalog snapshot");return "No keeps input; Yes discards; exact 7-table SHA256 unchanged";});
    await Check("T07-K04.keyboard.125","Tab/ShiftTab change focus; Enter does not save editor",async()=>{Current!.BeginInvoke((Action)(()=>F<Button>(control,"addButton").PerformClick()));await Wait(()=>Application.OpenForms.OfType<CatalogEditorDialog>().Any());var d=Application.OpenForms.OfType<CatalogEditorDialog>().Single();var text=F<TextBox>(d,"nameInput");text.Text="Keyboard draft";SetForegroundWindow(d.Handle);text.Focus();await Task.Delay(100);SendKeys.SendWait("{TAB}");await Task.Delay(100);Need(!text.Focused,"Tab unchanged");SendKeys.SendWait("+{TAB}");await Task.Delay(100);Need(text.Focused,"ShiftTab not returned");var before=await Snapshot();SendKeys.SendWait("{ENTER}");await Task.Delay(250);Need(!d.IsDisposed&&before==await Snapshot(),"Enter committed or closed");Capture(d,"keyboard");await Cancel(d,true);return "Native Tab/ShiftTab verified; Enter no commit, exact snapshot unchanged";});
    foreach(var size in new[]{new Size(1280,720),new Size(1366,768)})await Check("T07-K04.restore.125."+size.Width,"Minimize/restore preserves exact viewport",async()=>{Current!.Size=size;Current.WindowState=FormWindowState.Minimized;await Task.Delay(100);Current.WindowState=FormWindowState.Normal;await Task.Delay(150);Need(Current.Size==size,"Restore changed viewport");Capture(Current,"restored-"+size.Width);return "Restored "+Current.Size;});
   }
   var form=Current!;F<Button>(form,"logoutButton").PerformClick();await Wait(()=>Current is null&&Login.Visible);
  }
